script:
(function () {
  'use strict';
  // Roth vs pre-tax contributions to a governmental 457(b), followed through the withdrawal years.
  //   Saving: the same deferral goes in at the start of each year until you leave the job, then the
  //     balance keeps growing until withdrawals start. Both accounts therefore hold the same balance.
  //   Withdrawing: a level amount at the start of each year that uses up the balance over the chosen
  //     years (annuity-due: W = B / sum (1 + r)^-k, k = 0..n-1).
  //   Pre-tax: every withdrawal is taxed at the withdrawal tax rate. No 10% additional tax at any age
  //     after leaving the job, because IRC 72(t) does not reach governmental 457(b) money (except
  //     amounts rolled in from an IRA, 401(k) or 403(b), IRC 72(t)(9)).
  //   Roth: tax-free once qualified (age 59 1/2 and 5 taxable years after the first Roth deferral,
  //     IRC 402A(d)); before that each withdrawal is part contributions and part earnings in proportion
  //     (IRC 72(e)(8)) and only the earnings part is taxed. Ages are whole years at the start of each
  //     year, so the year you turn 59 counts as before 59 1/2.
  //   Optional side account: the yearly tax the pre-tax deferral saves (deferral x tax rate now),
  //     invested in a taxable account growing at return x (1 - tax on its growth) and paid out the same
  //     way over the same years.
  //   Break-even withdrawal tax rate: found by bisection (Roth minus pre-tax rises with the rate).
  // Checked in Node (scratch tests, whole script with a fake DOM):
  //   $10,000 a year for 20 years at 6% (start of year) = $389,927.27 = 10,000 x 1.06 x (1.06^20 - 1)/0.06.
  //   Withdrawing $389,927.27 over 10 years at 6% (start of year) = $49,979.83 (annuity-due formula),
  //     leaving exactly $0.
  //   All withdrawals qualified, savings not invested: pre-tax after tax = Roth x (1 - rate later)
  //     exactly, and the break-even rate is 0%. With savings invested and 0% tax on their growth the
  //     break-even rate equals the tax rate now (22.0%), the textbook result.
  //   Roth withdrawn before 59 1/2: $10,000 a year from 40 to 49 at 6% = $139,716 with $100,000 of
  //     contributions; the first $31,291 withdrawal at 50 has a $8,895 taxable part (28.4% earnings share).
  //   Maximum option from 58 to 64: $32,500 x 3 + $35,750 x 4 = $240,500.
  // ---- 2026 IRS limits (IRS Notice 2025-67, tax year 2026) -------------------------------------
  var LIMITS = { year: 2026, basic: 24500, catchUp50: 8000, catchUp60to63: 11250 }; // 457(e)(15), 414(v)
  var QUALIFIED_AGE = 60;   // first whole age treated as past 59 1/2 (IRC 402A(d)(2))
  var ROTH_YEARS = 5;       // five-taxable-year period for a qualified Roth distribution
  // ------------------------------------------------------------------------------------------------

  function maxFor(age) {
    if (age >= 60 && age <= 63) return LIMITS.basic + LIMITS.catchUp60to63;
    if (age >= 50) return LIMITS.basic + LIMITS.catchUp50;
    return LIMITS.basic;
  }
  function annuityDue(n, r) {
    var s = 0;
    for (var k = 0; k < n; k++) s += Math.pow(1 + r, -k);
    return s;
  }

  // p: age, leaveAge, startAge, years, contribution, useMax, rate, taxNow, taxLater, investTax, invest
  function simulate(p, taxLater) {
    var bal = 0, basis = 0, side = 0, total = 0, rows = [];
    var sideRate = p.rate * (1 - p.investTax);
    for (var a = p.age; a < p.startAge; a++) {
      var c = a < p.leaveAge ? (p.useMax ? maxFor(a) : p.contribution) : 0;
      bal = (bal + c) * (1 + p.rate);
      basis += c; total += c;
      if (p.invest) side = (side + c * p.taxNow) * (1 + sideRate);
      rows.push({ age: a, c: c, w: 0, taxable: 0, roth: 0, trad: 0, bal: bal });
    }
    var startBal = bal, startSide = side;
    var W = bal > 0 ? bal / annuityDue(p.years, p.rate) : 0;
    var Ws = side > 0 ? side / annuityDue(p.years, sideRate) : 0;
    var rothNet = 0, tradNet = 0, rothTax = 0, tradTax = 0, sidePaid = 0, early = 0, firstRoth = NaN, firstTrad = NaN;
    for (var y = 0; y < p.years; y++) {
      var age = p.startAge + y;
      var w = Math.min(W, bal), ws = Math.min(Ws, side);
      var qualified = age >= QUALIFIED_AGE && age - p.age >= ROTH_YEARS;
      var taxable = 0;
      if (!qualified && bal > 0 && bal > basis) taxable = w * (bal - basis) / bal;
      if (bal > 0) basis = Math.max(0, basis - w * Math.min(1, basis / bal));
      var rNet = w - taxable * taxLater, tNet = w * (1 - taxLater) + ws;
      rothNet += rNet; tradNet += tNet; rothTax += taxable * taxLater; tradTax += w * taxLater; sidePaid += ws;
      if (age < QUALIFIED_AGE) early += w;
      if (y === 0) { firstRoth = rNet; firstTrad = tNet; }
      bal = (bal - w) * (1 + p.rate);
      side = (side - ws) * (1 + sideRate);
      if (Math.abs(bal) < 1e-6) bal = 0;
      if (Math.abs(side) < 1e-6) side = 0;
      rows.push({ age: age, c: 0, w: w, taxable: taxable, roth: rNet, trad: tNet, bal: bal });
    }
    return { rows: rows, total: total, startBal: startBal, startSide: startSide, W: W, rothNet: rothNet, tradNet: tradNet,
             rothTax: rothTax, tradTax: tradTax, sidePaid: sidePaid, early: early, firstRoth: firstRoth, firstTrad: firstTrad,
             diff: rothNet - tradNet };
  }

  function breakEven(p) {
    var lo = 0, hi = 0.99;
    var dLo = simulate(p, lo).diff, dHi = simulate(p, hi).diff;
    if (dLo >= 0) return 0;
    if (dHi < 0) return NaN;
    for (var i = 0; i < 60; i++) {
      var mid = (lo + hi) / 2;
      if (simulate(p, mid).diff < 0) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return money.format(Math.abs(x) < 0.5 ? 0 : x); }
  function pct(x) { return (Math.round(x * 1000) / 10) + '%'; }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }

  function update() {
    var age = num('rpAge'), leaveAge = num('rpLeaveAge'), startAge = num('rpStartAge'), years = num('rpYears'),
        contribution = num('rpContrib'), rate = num('rpRate'), taxNow = num('rpTaxNow'), taxLater = num('rpTaxLater'),
        investTax = num('rpInvestTax'), useMax = document.getElementById('rpMax').checked,
        invest = document.getElementById('rpInvest').checked;
    document.getElementById('rpContrib').disabled = useMax;
    var error = document.getElementById('rpError');
    var ints = [age, leaveAge, startAge, years];
    var bad = ints.concat([rate, taxNow, taxLater, investTax]).some(isNaN) || (!useMax && isNaN(contribution)) ||
              ints.some(function (v) { return v !== Math.round(v); }) || age < 16 || age > 80 ||
              leaveAge <= age || leaveAge > 85 || startAge < leaveAge || startAge > 90 || years < 1 || years > 50 ||
              (!useMax && (contribution < 0 || contribution > LIMITS.basic + LIMITS.catchUp60to63)) ||
              rate < -20 || rate > 30 || taxNow < 0 || taxNow > 70 || taxLater < 0 || taxLater > 70 ||
              investTax < 0 || investTax > 70;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter whole-number ages (current 16 to 80, leaving the job after that, withdrawals starting no earlier ' +
                          'than you leave and by 90), 1 to 50 withdrawal years, a contribution from $0 to ' +
                          fmt(LIMITS.basic + LIMITS.catchUp60to63) + ', a return from -20 to 30% and tax rates up to 70%.';
      return;
    }
    var p = { age: age, leaveAge: leaveAge, startAge: startAge, years: years, contribution: contribution, useMax: useMax,
              rate: rate / 100, taxNow: taxNow / 100, investTax: investTax / 100, invest: invest };
    var r = simulate(p, taxLater / 100);
    var tie = Math.abs(r.diff) < 0.5;
    set('rpWinner', tie ? 'Even' : r.diff > 0 ? 'Roth 457(b)' : 'Pre-tax 457(b)');
    set('rpDiff', fmt(Math.abs(r.diff)));
    set('rpRothTotal', fmt(r.rothNet));
    set('rpTradTotal', fmt(r.tradNet));
    set('rpRothYear', fmt(r.firstRoth) + ' in the first withdrawal year');
    set('rpTradYear', fmt(r.firstTrad) + ' in the first withdrawal year');
    set('rpContributed', fmt(r.total));
    set('rpStartBal', fmt(r.startBal) + ' at age ' + startAge);
    set('rpGross', fmt(r.W) + ' for ' + years + (years === 1 ? ' year' : ' years'));
    set('rpTradTax', fmt(r.tradTax));
    set('rpRothTax', fmt(r.rothTax));
    set('rpSide', invest ? fmt(r.sidePaid) : 'Not invested');
    var be = r.startBal > 0 ? breakEven(p) : NaN;
    set('rpBreakEven', isFinite(be) ? pct(be) : '–');
    var earlyEl = document.getElementById('rpEarlyNote');
    earlyEl.hidden = !(r.early > 0);
    if (r.early > 0) {
      set('rpEarlyNote', 'You withdraw ' + fmt(r.early) + ' before 59½. From a governmental 457(b) after you leave the job that owes no ' +
          '10% additional tax. The same withdrawals from a traditional IRA would add ' + fmt(r.early * 0.1) +
          ' of extra tax, and money you rolled into the 457(b) from an IRA, 401(k) or 403(b) keeps that 10% rule.');
    }
    var rothEl = document.getElementById('rpRothNote');
    rothEl.hidden = !(r.rothTax > 0.5);
    if (r.rothTax > 0.5) {
      set('rpRothNote', 'Some Roth withdrawals come before they are qualified (age 59½ and 5 years after your first Roth ' +
          'contribution), so the earnings share of those withdrawals is taxed. The part that is your own contributions comes out tax-free.');
    }
    var body = document.getElementById('rpSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      var withdrawing = row.w > 0 || row.c === 0 && row.age >= startAge;
      [row.age, row.c > 0 ? fmt(row.c) : '–', withdrawing ? fmt(row.w) : '–', withdrawing ? fmt(row.taxable) : '–',
       withdrawing ? fmt(row.roth) : '–', withdrawing ? fmt(row.trad) : '–', fmt(row.bal)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rpForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
